5/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mauvais-Pr&#233;sage.html&quot; title=&quot;Mauvais pr&#233;sage&quot;&gt;mauvais pr&#233;sage&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 17)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
3/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Augure.html&quot; title=&quot;Augure&quot;&gt;augure&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Discours-Captivant.html&quot; title=&quot;Discours captivant&quot;&gt;discours captivant&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 18), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Festin-De-Cendres.html&quot; title=&quot;Festin de cendres&quot;&gt;festin de cendres&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 18)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayon-D&#233;puisement.html&quot; title=&quot;Rayon d&amp;#39;&#233;puisement&quot;&gt;rayon d’&#233;puisement&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 19)
&lt;/div&gt;
